#!/usr/bin/env bash
# Runs once when the Codespace / dev container is created.
set -euo pipefail
cd "$(dirname "$0")/.."

npm ci

if [ ! -f .env.local ]; then
  if [ -n "${CODESPACE_NAME:-}" ]; then
    url="https://${CODESPACE_NAME}-3000.${GITHUB_CODESPACES_PORT_FORWARDING_DOMAIN:-app.github.dev}"
  else
    url="http://127.0.0.1:3000"
  fi
  secret=$(node -e "console.log(require('node:crypto').randomBytes(48).toString('hex'))")
  cat > .env.local <<ENV
# Generated by .devcontainer/setup.sh for this development environment only.
DATABASE_URL=postgresql://pfm:pfm_local_only@localhost:5432/pfm
BETTER_AUTH_URL=${url}
BETTER_AUTH_SECRET=${secret}
PFM_LOCAL_MAIL=true
MAIL_TRANSPORT=local
# Demo accounts have no second factor; set to false to test MFA.
PFM_MFA_SUSPENDED=true
ENV
  echo "Created .env.local (BETTER_AUTH_URL=${url})"
fi

# PostgreSQL may still be starting.
for attempt in $(seq 1 30); do
  if npm run --silent db:migrate; then break; fi
  [ "$attempt" = 30 ] && { echo "PostgreSQL unreachable"; exit 1; }
  sleep 2
done
npm run db:test
npm run demo:seed
npm run build
